mapper.select:
SELECT movie_id AS movieId, title, poster_url AS posterUrl, genres_json AS genresJson, rating, duration_min AS durationMin, release_date AS releaseDate, status, description, cast_text AS castText, want_see_count AS wantSeeCount, created_at AS createdAt, updated_at AS updatedAt FROM movie
AND status = #{status} AND title LIKE '%' || #{q} || '%' AND genres_json::text LIKE '%' || #{genre} || '%'
ORDER BY want_see_count DESC LIMIT #{limit} OFFSET #{offset}
